import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    try:
        n = int(next(iterator))
        arr = []
        for _ in range(n):
            arr.append(next(iterator))
        str_val = next(iterator)
        k = int(next(iterator))
    except StopIteration:
        return

    target_prefix = str_val[:k]
    count = 0

    for s in arr:
        if len(s) >= k and s[:k] == target_prefix:
            count += 1

    print(count)

if __name__ == "__main__":
    main()
